template <typename C>
const typename C::value_type& SafeFront(const C& container) {
    if (container.empty()) {
        throw std::out_of_range("Container empty.");
    }
    return container.front();
}

template <typename C, typename Index>
typename C::reference SafeAt(C& container, Index i) {
    if (i >= container.size()) {
        throw std::out_of_range("Index out of bounds.");
    }
    return container[i];
}
